except ValueError:
    pass

ex.sol:
def chunks(words, size, overlap):
    if overlap >= size:
        raise ValueError('overlap must be smaller than size')
    step = size - overlap
    for start in range(0, len(words), step):
        yield words[start:start + size]
        if start + size >= len(words):
            break

